<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { ElMessage, ElMessageBox } from 'element-plus'; import { Icon } from '@iconify/vue'
import StatusBadge from '../../components/common/StatusBadge.vue'; import ErrorState from '../../components/common/ErrorState.vue'; import EmptyState from '../../components/common/EmptyState.vue'; import RiskBanner from '../../components/diagnosis/RiskBanner.vue'; import DiagnosisResult from '../../components/diagnosis/DiagnosisResult.vue'; import DiagnosisProgress from '../../components/diagnosis/DiagnosisProgress.vue'; import EvidencePanel from '../../components/diagnosis/EvidencePanel.vue'; import DoctorReviewDrawer from '../../components/diagnosis/DoctorReviewDrawer.vue'
import { getCase } from '../../api/case'; import { getPatientOverview } from '../../api/patient'; import { submitReview } from '../../api/review'; import { useCaseStream } from '../../composables/useCaseStream'; import type { MedicalCase } from '../../types/case'; import type { PatientOverview } from '../../types/patient'; import type { ReviewRequest } from '../../types/diagnosis'; import { sexLabel } from '../../utils/medical'; import { apiErrorMessage } from '../../utils/request'
const route = useRoute(); const router = useRouter(); const caseId = String(route.params.caseId); const current = ref<MedicalCase | null>(null); const patient = ref<PatientOverview | null>(null); const loading = ref(true); const error = ref(''); const reviewDrawer = ref(false); const reviewing = ref(false)
const { events, connect } = useCaseStream(caseId, async () => { await loadCase(false) })
const result = computed(() => current.value?.doctor_result || current.value?.ai_result || null)
async function loadCase(initial = true) { if (initial) loading.value = true; try { current.value = await getCase(caseId); if (!patient.value) patient.value = await getPatientOverview(current.value.patient_id); if (current.value.status === 'RUNNING' && initial) connect() } catch { error.value = '病例工作台加载失败' } finally { loading.value = false } }
async function review(payload: ReviewRequest) { if (!current.value) return; reviewing.value = true; try { current.value = await submitReview(caseId, payload); reviewDrawer.value = false; ElMessage.success(payload.action === 'reject' ? '病例已驳回' : '医生审核已完成') } catch (e) { ElMessage.error(apiErrorMessage(e, '审核提交失败')); await loadCase(false) } finally { reviewing.value = false } }
async function approve() { if (!current.value) return; await ElMessageBox.confirm('确认将当前 AI 辅助意见审核通过？通过后将形成医生审核结果。', '审核通过', { type: 'warning', confirmButtonText: '确认通过' }); await review({ action: 'approve', expected_version: current.value.assessment_version }) }
async function reject() { if (!current.value) return; const { value } = await ElMessageBox.prompt('请说明当前意见被驳回的原因。', '驳回 AI 辅助意见', { inputType: 'textarea', inputValidator: v => Boolean(v.trim()) || '请填写驳回原因', confirmButtonText: '确认驳回' }); await review({ action: 'reject', expected_version: current.value.assessment_version, reason: value }) }
onMounted(loadCase)
</script>
<template><main class="workspace"><el-skeleton v-if="loading" class="page-shell" :rows="12" animated /><ErrorState v-else-if="error || !current" :message="error" @retry="loadCase" /><template v-else><header class="case-header"><button class="back" aria-label="返回病例列表" @click="router.push('/cases')"><Icon icon="solar:arrow-left-linear" /></button><div><div class="case-title"><span class="mono">{{ current.id }}</span><StatusBadge type="status" :value="current.status" /></div><p>{{ current.question }}</p></div><div class="case-meta"><span>{{ patient?.summary.display_name || current.patient_id }}</span><span>{{ patient ? sexLabel(patient.summary.sex) : '—' }}</span><StatusBadge type="risk" :value="current.risk_level" /><router-link :to="`/cases/${current.id}/history`">诊断复盘</router-link></div></header>
  <RiskBanner v-if="current.risk_level" class="risk-top" :risk="current.risk_level" />
  <div class="workspace-grid"><aside class="context-column"><section><header><h2>患者临床上下文</h2><router-link :to="`/patients/${current.patient_id}`">完整档案</router-link></header><div class="context-block"><label>当前主诉 / 问题</label><p>{{ current.question }}</p></div><div class="context-block"><label>既往史与慢性病</label><p>{{ patient?.summary.summary.history?.join('、') || '暂无重要既往史记录' }}</p></div><div class="context-block"><label>当前用药</label><ul><li v-for="item in patient?.current_medications || []" :key="item.id">{{ item.name }} {{ item.dose }}</li><li v-if="!patient?.current_medications.length">暂无当前用药记录</li></ul></div><div class="context-block alert"><label>药物过敏</label><p>{{ patient?.allergies.map(i => `${i.substance}（${i.reaction || '反应未记录'}）`).join('、') || '暂无已记录药物过敏' }}</p></div><div class="context-block"><label>近期检验</label><ul><li v-for="item in patient?.recent_labs.slice(0, 4) || []" :key="item.id">{{ item.test_name }}：{{ item.value }} <span v-if="item.abnormal_flag !== 'normal'">{{ item.abnormal_flag }}</span></li><li v-if="!patient?.recent_labs.length">暂无近期检验</li></ul></div><div class="context-block"><label>近期影像</label><p>{{ patient?.recent_imaging[0]?.impression || '暂无近期影像检查' }}</p></div></section></aside>
  <section class="result-column surface"><div v-if="current.status === 'RUNNING'" class="analysis-state"><span class="pulse"><Icon icon="solar:health-linear" /></span><h2>AI 正在进行结构化临床分析</h2><p>您可以在右侧查看实时流程。病例数据已经保存，离开页面不会丢失。</p><el-progress :percentage="Math.min(88, 12 + events.length * 13)" :show-text="false" /></div><div v-else-if="current.status === 'FAILED'" class="analysis-state failed"><Icon icon="solar:danger-circle-linear" /><h2>AI 分析暂时失败</h2><p>病例数据已经保存，可稍后刷新状态。系统不会将失败结果标记为诊断结论。</p><el-button @click="loadCase(false)">刷新状态</el-button></div><DiagnosisResult v-else-if="result" :result="result" /><EmptyState v-else title="尚未生成 AI 辅助意见" /></section>
  <aside class="process-column"><section class="surface"><header><h2>诊断过程</h2><span>实时</span></header><DiagnosisProgress :events="events" :status="current.status" /></section><section class="surface evidence"><header><h2>医学证据</h2><span>{{ result?.rag_enabled ? 'RAG' : '未启用' }}</span></header><EvidencePanel :enabled="Boolean(result?.rag_enabled)" :evidence="result?.evidence || []" /></section></aside></div>
  <footer v-if="current.status === 'WAITING_REVIEW' && current.ai_result" class="review-bar"><div><span class="review-dot" /><p><strong>AI 辅助意见 · 等待医生审核</strong><small>未经审核的内容不是最终临床诊断</small></p></div><div><el-button :disabled="reviewing" @click="reject">驳回</el-button><el-button :disabled="reviewing" @click="reviewDrawer = true">编辑诊断</el-button><el-button type="primary" :loading="reviewing" @click="approve">审核通过</el-button></div></footer>
  <DoctorReviewDrawer v-if="current.ai_result" v-model="reviewDrawer" :result="current.ai_result" :version="current.assessment_version" :loading="reviewing" @submit="review" /></template></main></template>
<style scoped lang="scss">.workspace { min-height: calc(100vh - 68px); padding-bottom: 90px; }.case-header { min-height: 78px; background: white; border-bottom: 1px solid var(--border); display: flex; align-items: center; gap: 14px; padding: 12px 24px; position: sticky; top: 68px; z-index: 10; }.back { width: 34px; height: 34px; border: 1px solid var(--border); border-radius: 8px; background: white; display: grid; place-items: center; cursor: pointer; }.case-title { display: flex; align-items: center; gap: 9px; }.case-title .mono { font-size: 12px; font-weight: 700; }.case-header p { margin: 5px 0 0; color: var(--text-secondary); font-size: 12px; max-width: 600px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }.case-meta { margin-left: auto; display: flex; gap: 13px; align-items: center; color: var(--text-secondary); font-size: 12px; }.case-meta a { color: var(--primary); font-weight: 650; }.risk-top { margin: 14px 18px 0; }.workspace-grid { display: grid; grid-template-columns: minmax(260px, 26fr) minmax(480px, 48fr) minmax(270px, 26fr); gap: 14px; padding: 14px 18px; align-items: start; }.context-column > section, .process-column > section { background: white; border-radius: var(--radius); box-shadow: var(--shadow); padding: 18px; }.context-column header, .process-column header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }.context-column h2, .process-column h2 { margin: 0; font-size: 14px; }.context-column header a, .process-column header span { color: var(--primary); font-size: 11px; }.context-block { padding: 13px 0; border-top: 1px solid var(--border); }.context-block label { color: var(--text-tertiary); font-size: 10px; font-weight: 700; letter-spacing: .05em; }.context-block p, .context-block li { font-size: 12px; line-height: 1.6; }.context-block p { margin: 6px 0 0; }.context-block ul { margin: 6px 0 0; padding-left: 17px; }.context-block li { margin: 3px 0; }.context-block.alert p { color: #9a3412; }.result-column { overflow: hidden; min-height: 610px; }.analysis-state { min-height: 600px; display: grid; place-items: center; align-content: center; padding: 50px; text-align: center; }.analysis-state .pulse { width: 64px; height: 64px; display: grid; place-items: center; border-radius: 18px; color: var(--primary); background: #edf4ff; font-size: 30px; animation: pulse 1.8s infinite; }.analysis-state h2 { font-size: 18px; margin: 20px 0 8px; }.analysis-state p { color: var(--text-secondary); font-size: 13px; line-height: 1.6; max-width: 430px; }.analysis-state .el-progress { width: min(420px, 100%); margin-top: 18px; }.analysis-state.failed > svg { font-size: 44px; color: var(--risk-emergency); }.process-column { display: grid; gap: 14px; }.evidence { padding-bottom: 14px !important; }.review-bar { position: fixed; left: var(--sidebar-width); right: 0; bottom: 0; z-index: 30; min-height: 74px; padding: 12px 24px; background: white; border-top: 1px solid var(--border); box-shadow: 0 -8px 30px rgb(16 24 40 / 8%); display: flex; justify-content: space-between; align-items: center; }.review-bar > div { display: flex; align-items: center; gap: 12px; }.review-bar p { display: grid; margin: 0; gap: 3px; }.review-bar small { color: var(--text-secondary); }.review-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--risk-medium); box-shadow: 0 0 0 5px #fff3cd; }@keyframes pulse { 50% { transform: scale(1.04); box-shadow: 0 0 0 12px rgb(37 99 235 / 6%); } }@media (max-width: 1280px) { .workspace-grid { grid-template-columns: 300px 1fr; }.process-column { grid-column: 1 / -1; grid-template-columns: 1fr 1fr; }.review-bar { left: 72px; } }@media (max-width: 800px) { .case-header { top: 68px; flex-wrap: wrap; }.case-meta { width: 100%; margin: 0; flex-wrap: wrap; }.workspace-grid { grid-template-columns: 1fr; padding: 10px; }.process-column { grid-column: auto; grid-template-columns: 1fr; }.review-bar { left: 0; flex-direction: column; align-items: stretch; padding: 10px 14px; }.review-bar > div:last-child { justify-content: flex-end; } }</style>
